import React from 'react';

const RegistrationLink = () => {
    return (
        <div>
            <h2>Apply for SoochnaPreneur</h2>
            <p>Join us in making a difference! Click the link below to register for the SoochnaPreneur initiative.</p>
            <a href="/registration" className="registration-link">Register Now</a>
        </div>
    );
};

export default RegistrationLink;
